<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\Theme\Domain\Gateway;

use Override;
use ArrayIterator;

use Civi\Lughauth\Features\Document\Theme\Domain\ThemeAttributes;

/**
 * @template-extends ArrayIterator<int, ThemeAttributes>
 */
class ThemeAttributesSlide extends ArrayIterator
{
  public function __construct(
    private readonly ?ThemeCursor $cursor,
    private readonly array $values
  ) {
    parent::__construct($values);
  }
  public function cursor(): ?ThemeCursor
  {
    return $this->cursor;
  }
  public function values(): array
  {
    return $this->values;
  }
  #[Override]
  public function current(): ?ThemeAttributes
  {
    return parent::current();
  }
}
